from collections import Counter


def longestSubstringAtLeastK(s, k):
    def solve(t):
        if len(t) < k:
            return 0
        cnt = Counter(t)
        bad = {c for c, v in cnt.items() if v < k}
        if not bad:
            return len(t)
        best = 0
        start = 0
        for i, c in enumerate(t):
            if c in bad:
                if i - start >= k:
                    best = max(best, solve(t[start:i]))
                start = i + 1
        if len(t) - start >= k:
            best = max(best, solve(t[start:]))
        return best

    return solve(s)
